```python
import numpy as np

class Model:
    def __init__(self):
        self.weights = None

    def fit(self, X, y):
        raise NotImplementedError("Subclasses must implement this method")

    def predict(self, X):
        raise NotImplementedError("Subclasses must implement this method")

class LinearModel(Model):
    def fit(self, X, y):
        # Simple linear regression using least squares
        self.weights = np.linalg.inv(X.T @ X) @ X.T @ y

    def predict(self, X):
        return X @ self.weights

class RandomModel(Model):
    def fit(self, X, y):
        pass

    def predict(self, X):
        return np.random.rand(len(X))

class DecisionTreeModel(Model):
    def fit(self, X, y):
        # Placeholder for decision tree fitting logic
        pass

    def predict(self, X):
        # Placeholder for decision tree prediction logic
        return np.random.rand(len(X))

class ContextualMultiArmedBandit:
    def __init__(self, models):
        self.models = models
        self.rewards = {model: [] for model in models}

    def select_arm(self, context):
        predictions = [model.predict([context])[0] for model in self.models]
        selected_model_index = np.argmax(predictions)
        return selected_model_index

    def update(self, arm, reward):
        self.rewards[self.models[arm]].append(reward)

# Example usage
if __name__ == "__main__":
    # Generate some synthetic data
    np.random.seed(42)
    n_samples = 1000
    n_features = 5
    contexts = np.random.rand(n_samples, n_features)
    true_rewards = np.random.rand(n_samples)

    # Initialize models
    linear_model = LinearModel()
    random_model = RandomModel()
    decision_tree_model = DecisionTreeModel()

    # Train models on the first half of the data
    train_contexts = contexts[:n_samples//2]
    train_rewards = true_rewards[:n_samples//2]

    linear_model.fit(train_contexts, train_rewards)
    random_model.fit(train_contexts, train_rewards)
    decision_tree_model.fit(train_contexts, train_rewards)

    # Create and run the contextual multi-armed bandit
    cma_bandit = ContextualMultiArmedBandit([linear_model, random_model, decision_tree_model])

    test_contexts = contexts[n_samples//2:]
    for i, context in enumerate(test_contexts):
        arm = cma_bandit.select_arm(context)
        reward = true_rewards[i + n_samples//2]
        cma_bandit.update(arm, reward)

    print("Rewards per model:", cma_bandit.rewards)
```

This script defines three types of models (`LinearModel`, `RandomModel`, and `DecisionTreeModel`) that can be used within a `ContextualMultiArmedBandit` class. The bandit selects an arm based on the predicted rewards from each model given a context vector. After selecting an arm, it updates its internal state with the actual reward received. This setup allows you to experiment with different strategies for choosing arms in a contextual setting.

