        {
            foreach (var header in sourcePart.HeaderParts.Values)
            {
                var newHeader = targetPart.AddNewPart<HeaderPart>();
                newHeader.Header = header.Header.CloneNode(true);
            }

            foreach (var footer in sourcePart.FooterParts.Values)
            {
                var newFooter = targetPart.AddNewPart<FooterPart>();
                newFooter.Footer = footer.Footer.CloneNode(true);
            }
        }
    }

    private static void CopyPages(Body sourceBody, MainDocumentPart targetPart, int numberOfPages)
    {
        if (sourceBody != null && targetPart != null)
        {
            List<Paragraph> paragraphsToCopy = new List<Paragraph>();

            // Collect paragraphs up to the specified number of pages
            int currentPage = 0;
            foreach (var paragraph in sourceBody.Elements<Paragraph>())
            {
