```c
#include <stdio.h>
#include <stdlib.h>

#define REVERB_SIZE 1024

typedef struct {
    float buffer[REVERB_SIZE];
    int head;
} Reverb;

Reverb* create_reverb() {
    Reverb* reverb = (Reverb*)malloc(sizeof(Reverb));
    for (int i = 0; i < REVERB_SIZE; i++) {
        reverb->buffer[i] = 0.0f;
    }
    reverb->head = 0;
    return reverb;
}

void destroy_reverb(Reverb* reverb) {
    free(reverb);
}

float apply_reverb(Reverb* reverb, float input) {
    const float decay = 0.5f;
    const float mix = 0.3f;

    // Apply delay
    reverb->buffer[(reverb->head + 1) % REVERB_SIZE] = input * decay;
    float delayed = reverb->buffer[reverb->head];

    // Update head position
    reverb->head = (reverb->head + 1) % REVERB_SIZE;

    // Mix original and delayed signal
    return input * (1.0f - mix) + delayed * mix;
}
```

