        val ethHeaderLength = 14
        val ipHeaderStart = ethHeaderLength + 20 // Assuming IPv4 header length
        val ipHeaderEnd = ipHeaderStart + 20
        val ipHeader = packet.sliceArray(ipHeaderStart until ipHeaderEnd)

        // Extract the destination IP address from the IP header
        val destIpBytes = ipHeader.sliceArray(12..15)
        return "${destIpBytes[0]}.${destIpBytes[1]}.${destIpBytes[2]}.${destIpBytes[3]}"
    }

    private fun sendPacket(packet: ByteArray) {
        val outputStream = FileOutputStream(vpnInterface!!.fileDescriptor)
        outputStream.write(packet)
        outputStream.close()
    }

    override fun onDestroy() {
        super.onDestroy()
        vpnInterface?.close()
    }
