```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC1155/ERC1155.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract CredsToken is ERC1155, Ownable {
    // Event to log when a new credential type is added
    event CredentialTypeAdded(uint256 indexed id);

    // Mapping to store metadata for each credential type
    mapping(uint256 => string) private _credentialMetadata;

    constructor() ERC1155("https://example.com/api/v1/creds/{id}.json") {}

    /**
     * @dev Adds a new credential type.
     * @param id The ID of the new credential type.
     * @param uri The URI for the metadata of the new credential type.
     */
    function addCredentialType(uint256 id, string memory uri) external onlyOwner {
        require(_exists(id) == false, "CredsToken: Credential type already exists");
        _setURI(uri);
        emit CredentialTypeAdded(id);
    }

    /**
     * @dev Sets the metadata for a specific credential type.
     * @param id The ID of the credential type.
     * @param metadata The metadata for the credential type.
     */
    function setCredentialMetadata(uint256 id, string memory metadata) external onlyOwner {
        require(_exists(id), "CredsToken: Credential type does not exist");
        _credentialMetadata[id] = metadata;
    }

    /**
     * @dev Returns the metadata for a specific credential type.
     * @param id The ID of the credential type.
     * @return The metadata for the credential type.
     */
    function getCredentialMetadata(uint256 id) public view returns (string memory) {
        return _credentialMetadata[id];
    }

    /**
     * @dev Mints a specified amount of a credential type to a recipient.
     * @param to The address of the recipient.
     * @param id The ID of the credential type.
     * @param amount The amount of the credential type to mint.
     */
    function mint(address to, uint256 id, uint256 amount) external onlyOwner {
        _mint(to, id, amount, "");
    }

    /**
     * @dev Burns a specified amount of a credential type from the caller's balance.
     * @param id The ID of the credential type.
     * @param amount The amount of the credential type to burn.
     */
    function burn(uint256 id, uint256 amount) external {
        require(balanceOf(msg.sender, id) >= amount, "CredsToken: Insufficient balance");
        _burn(msg.sender, id, amount);
    }
}
```

### Explanation:

1. **Imports**: We import necessary OpenZeppelin contracts (`ERC1155` and `Ownable`) to handle the core functionality and ownership checks.

2. **Contract Definition**: The `CredsToken` contract inherits from both `ERC1155` and `Ownable`.

3. **Events**:
   - `CredentialTypeAdded`: Logs when a new credential type is added.

4. **Mappings**:
   - `_credentialMetadata`: Stores metadata for each credential type.

5. **Constructor**: Initializes the base URI for the token metadata.

6. **Functions**:
   - `addCredentialType`: Allows the owner to add a new credential type by setting its URI.
   - `setCredentialMetadata`: Allows the owner to update the metadata for a specific credential type.
   - `getCredentialMetadata`: Retrieves the metadata for a specific credential type.
   - `mint`: Allows the owner to mint a specified amount of a credential type to a recipient.
   - `burn`: Allows any user to burn a specified amount of a credential type from their balance.

