Here's a simple example of a Metal compute kernel for Gaussian blurring an image:

```metal
#include <metal_stdlib>
using namespace metal;

kernel void gaussian_blur(
    texture2d<float, access::read> input [[texture(0)]],
    texture2d<float, access::write> output [[texture(1)]],
    uint2 gid [[thread_position_in_grid]]
) {
    float4 color = float4(0);

    // Define the Gaussian weights for each direction (horizontal and vertical)
    const float horizontalWeights[5] = { 0.2736, 0.4598, 0.2736 };
    const float verticalWeights[5] = { 0.2736, 0.4598, 0.2736 };

    // Apply horizontal pass
    for (int i = -1; i <= 1; ++i) {
        int x = gid.x + i;
        if (x >= 0 && x < input.get_width()) {
            color += input.read({ x, gid.y }) * horizontalWeights[i + 1];
        }
    }

    // Apply vertical pass
    for (int j = -1; j <= 1; ++j) {
        int y = gid.y + j;
        if (y >= 0 && y < input.get_height()) {
            color += output.read({ gid.x, y }) * verticalWeights[j + 1];
        }
    }

    output.write(color, gid);
}
```

This code defines a `gaussian_blur` function that takes two textures as input: one for reading the original image (`input`) and another for writing the blurred result (`output`). The kernel applies a separable Gaussian filter by first performing a horizontal pass over the image using predefined weights, then applying a vertical pass with the same weights.

