For simplicity, let's consider a very small neural network with one input layer (784 neurons), one hidden layer (128 neurons), and one output layer (10 neurons). This example will not be optimized for performance or accuracy but serves as a starting point.

First, make sure you have installed Xilinx Vitis HLS and set up your development environment.

Create a new C++ file named `mnist_nn.cpp`:

```cpp
#include <ap_int.h>
#include <hls_stream.h>

// Define constants
#define INPUT_SIZE 784
#define HIDDEN_SIZE 128
#define OUTPUT_SIZE 10

// Function prototypes
void multiply(ap_uint<32> *input, ap_uint<32> *weights, ap_uint<32> *output, int size);
void relu(ap_uint<32> *input, ap_uint<32> *output, int size);

// Multiply function
void multiply(ap_uint<32> *input, ap_uint<32> *weights, ap_uint<32> *output, int size) {
    #pragma HLS INTERFACE m_axi port=input offset=slave bundle=gmem0
    #pragma HLS INTERFACE m_axi port=weights offset=slave bundle=gmem1
    #pragma HLS INTERFACE m_axi port=output offset=slave bundle=gmem2
    #pragma HLS INTERFACE s_axilite port=input bundle=control
    #pragma HLS INTERFACE s_axilite port=weights bundle=control
    #pragma HLS INTERFACE s_axilite port=output bundle=control
    #pragma HLS INTERFACE s_axilite port=size bundle=control

    for (int i = 0; i < size; ++i) {
        #pragma HLS PIPELINE II=1
        output[i] = 0;
        for (int j = 0; j < size; ++j) {
            output[i] += input[j] * weights[i * size + j];
        }
    }
}

// ReLU activation function
void relu(ap_uint<32> *input, ap_uint<32> *output, int size) {
    #pragma HLS INTERFACE m_axi port=input offset=slave bundle=gmem0
    #pragma HLS INTERFACE m_axi port=output offset=slave bundle=gmem1
    #pragma HLS INTERFACE s_axilite port=input bundle=control
    #pragma HLS INTERFACE s_axilite port=output bundle=control
    #pragma HLS INTERFACE s_axilite port=size bundle=control

    for (int i = 0; i < size; ++i) {
        #pragma HLS PIPELINE II=1
        if (input[i] > 0)
            output[i] = input[i];
        else
            output[i] = 0;
    }
}

// Main function
void mnist_nn(ap_uint<32> *input, ap_uint<32> *hidden_weights, ap_uint<32> *output_weights, ap_uint<32> *hidden_output, ap_uint<32> *final_output) {
    // Hidden layer
    multiply(input, hidden_weights, hidden_output, INPUT_SIZE);
    relu(hidden_output, hidden_output, HIDDEN_SIZE);

    // Output layer
    multiply(hidden_output, output_weights, final_output, HIDDEN_SIZE);
}
```

This code defines two functions: `multiply` and `relu`. The `multiply` function performs matrix multiplication between the input data and weight matrices, while the `relu` function applies the Rectified Linear Unit (ReLU) activation function element-wise on the result.

The main function `mnist_nn` takes four parameters: `input`, `hidden_weights`, `output_weights`, and `hidden_output`. It first computes the hidden layer by multiplying the input data with the hidden weights and applying the ReLU activation function. Then, it computes the final output by multiplying the hidden layer output with the output weights.

