```rust
fn main() {
    let mut count = 0;

    // This closure captures `count` by mutable reference and thus implements `FnMut`.
    let increment = || {
        count += 1;
    };

    // To make it implement `Fn`, we need to capture `count` by immutable reference.
    let increment_fn = || {
        count += 1; // Error: cannot assign to `count` because it is borrowed
    };

    // Alternatively, if you want to keep using mutable references,
    // you can wrap the closure inside another function or method.
    fn increment_wrapper(count: &mut i32) {
        *count += 1;
    }

    // Now you can pass `increment_wrapper` as a closure that implements `Fn`.
    let increment_fn = || increment_wrapper(&mut count);

    // Call the closure multiple times without any issues.
